import java.util.List;

/**
 * 主备播出链路租约切换与游标回执仲裁核心服务。
 *
 * <p>同一频道任一时刻至多一条 ACTIVE 租约；切换在单事务内重验并原子结束源租约、
 * 创建 generation+1 的目标租约、冻结切点/编排版本/插播栈。回执按世代仲裁：旧世代只存 LATE，
 * 不推进频道游标，同代重复只结算一次，公开游标只能连续递增。</p>
 */
@Service
public class FailoverService {

    /** 目标回执落后源已确认序列的上限：超过则不得激活。 */
    public static final long MAX_LAG = 32L;

    private final FailoverRepository repo;

    public FailoverService(FailoverRepository repo) {
        this.repo = repo;
    }

    /** 配置主备链路；首次配置为主链路创建 generation=1 的 ACTIVE 租约。 */
    @Transactional
    public List<LinkResponse> configureLinks(String channelId, ConfigureLinksRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 上报链路运行态（健康、已缓存编排版本、已同步插播签名）。 */
    @Transactional
    public List<LinkResponse> reportLinkState(String channelId, String linkId, LinkStateRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 预览安全切点，只读不写数据。 */
    @Transactional(readOnly = true)
    public FailoverPreviewResponse preview(ActivateFailoverRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 激活切换单：事务内整体重验，任一变化 409/422；成功原子切换并冻结证据。 */
    @Transactional
    public FailoverOrderResponse activate(ActivateFailoverRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 提交链路回执：当前世代推进连续游标，旧世代/非活动链路记 LATE，重复只结算一次。 */
    @Transactional
    public ReceiptResponse submitReceipt(ReceiptRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 查询租约世代、切点、迟到回执与编排证据（只读）。 */
    @Transactional(readOnly = true)
    public FailoverStateResponse getState(String channelId) {
        throw new UnsupportedOperationException();
    }
}

